BV.markers = () => ({ live: MK.items.size, tier: _appliedTier });
BV.mkDemo = (x, z) => { const m = makeMapPin(0xff44aa, () => ({ x: x || player.pos.x, z: z || player.pos.z, y: mapElevY(x || player.pos.x, z || player.pos.z) + 8 }), { title: 'demo pin' }); return !!m; };
