    while (rd > minR * 0.55 && P.isW(lx, lz)) { rd -= 0.6; lx = keep.lx + Math.cos(ang[k]) * rd; lz = keep.lz + Math.sin(ang[k]) * rd; } // smoothing may have pushed it wet — pull ashore
