    const v = verts[i], gate = gateTower.has(i), th = wallH + ((gate ? 2.2 : 0.9) + r() * 0.4) * mh, rad = (gate ? 1.05 : 0.78) * tw;
    sgPrism(S, v.lx, v.y - 0.7, v.lz, rad, th + 0.7, stone);
