BV.animPause = () => { ANIM.playing = false; animPanelSync(); return 'paused'; };
BV.animStage = (i) => { animScrub(ANIM_SEQ.slice(0, clamp(i, 0, ANIM_SEQ.length - 1)).reduce((s, x) => s + x.dur, 0) + 1e-3); return ANIM_SEQ[ANIM.idx].name; };
