    if (b.mounted) { b.rsp = lerp(b.rsp || 0, Math.hypot(b.x - ox, b.z - oz) / Math.max(dt, 1e-3), clamp(dt * 6, 0, 1)); b.sp01 = clamp(b.rsp / (AF_F.move * AF_F.horseSpeed), 0, 1); }
