    const hs = AF.horses.map(h => [h.id, Math.round(h.x * 100), Math.round(h.z * 100), Math.round(h.yaw * 100), Math.round(h.hp), h.rider ? h.rider.idx : -1, h.dead ? 1 : 0]);
