  P.blur.uniforms.dir.value.set(0, P.blurStep.y); pass(P.blur, P.rb.texture, P.ra);
  P.blur.uniforms.dir.value.set(P.blurStep.x * 2, 0); pass(P.blur, P.ra.texture, P.rb);
